                    [TERMINAL]
                </button>

                <div className="flex gap-2">
                    <button onClick={() => toggleTheme('#4CA9FF', '#2B5C8A')} className="w-3 h-3 bg-[#4CA9FF] rounded-full hover:scale-125 transition-transform" title="Blue"></button>
                    <button onClick={() => toggleTheme('#FFD700', '#B89B00')} className="w-3 h-3 bg-[#FFD700] rounded-full hover:scale-125 transition-transform" title="Yellow"></button>
                    <button onClick={() => toggleTheme('#FF4C4C', '#990000')} className="w-3 h-3 bg-[#FF4C4C] rounded-full hover:scale-125 transition-transform" title="Red"></button>
                </div>
            </div>
        </div>
    </div>
  );
